{
  "root_causes": [
    {
      "service": "ts-basic-service",
      "fault_kind": "network_partition",
      "evidence": [
        {
          "kind": "log",
          "sql": "SELECT COUNT(*) AS n_timeouts_to_train FROM abnormal_logs WHERE service_name='ts-basic-service' AND level='SEVERE' AND message LIKE '%ts-train-service%Connection timed out%'",
          "claim": "ts-basic-service SEVERE logs repeatedly show I/O 'Connection timed out' on POST to ts-train-service trains/byNames."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' period, COUNT(*) n_byNames_server_spans FROM normal_traces WHERE service_name='ts-train-service' AND span_name='POST /api/v1/trainservice/trains/byNames' UNION ALL SELECT 'abnormal', COUNT(*) FROM abnormal_traces WHERE service_name='ts-train-service' AND span_name='POST /api/v1/trainservice/trains/byNames'",
          "claim": "Train service received 508 byNames calls in normal period but only 1 in the abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_status_code, COUNT(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, MAX(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND span_name='POST' AND attr_span_kind='Client' GROUP BY 1",
          "claim": "Basic's outgoing POST client spans either succeed in ~7ms or fail after ~129s with no child span, i.e. the connection hangs."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, COUNT(*) n, SUM(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, quantile_cont(c.duration,0.5)/1e6 callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND c.service_name<>p.service_name GROUP BY ALL ORDER BY callee_err DESC, n DESC",
          "claim": "ts-travel-service's calls to ts-basic-service all fail with 500s after about 130 seconds."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, COUNT(*) n, SUM(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, quantile_cont(c.duration,0.5)/1e6 callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND c.service_name<>p.service_name GROUP BY ALL ORDER BY callee_err DESC, n DESC",
          "claim": "ts-travel2-service's calls to ts-basic-service fail with errors after about 130 seconds, while basic's own calls are stalled."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, COUNT(*) n, SUM(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-route-plan-service' AND c.service_name IN ('ts-travel-service','ts-travel2-service') GROUP BY ALL",
          "claim": "Route-plan's calls to travel and travel2 include errors, so route-plan's own requests fail after travel's failures."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, COUNT(*) n, SUM(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, quantile_cont(c.duration,0.5)/1e6 callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND c.service_name<>p.service_name AND p.service_name='ts-travel-plan-service' GROUP BY ALL",
          "claim": "Travel-plan's calls to route-plan fail with errors after about 131 seconds."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, COUNT(*) n, SUM(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND attr_span_kind='Server' GROUP BY ALL ORDER BY 1,2",
          "claim": "Travel-plan server spans show errors and about 131s p95 latency, and ui-dashboard shows 20s requests."
        }
      ]
    }
  ]
}
